import{_ as a,o as l,c as t,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"Ceph Performance Meeting 2021-07-01","description":"","frontmatter":{"title":"Ceph Performance Meeting 2021-07-01","date":"2021-07-01T00:00:00.000Z","updated":"2021-08-25T00:00:00.000Z","tags":["Ceph性能优化","分布式存储","BlueFS","流控制","CPU分区"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Performance_Meeting_2021-07-01.md","filePath":"posts/2021/Ceph_Performance_Meeting_2021-07-01.md","lastUpdated":1780460162000}'),r={name:"posts/2021/Ceph_Performance_Meeting_2021-07-01.md"};function o(n,e,s,u,h,d){return l(),t("div",null,[...e[0]||(e[0]=[i('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>新Pull Request讨论</strong></p><ul><li>本次会议讨论了两个新的Pull Request。Adam提交的PR旨在BlueFS中实现细粒度锁定，但尚未准备好合并，因为存在死锁的可能性，需要进一步审查。另一个小的PR涉及将long double改为double，对性能有一定提升。</li><li>Patrick在MDS中合并了一个PR，用于在请求读锁时刷新MD Log，而Kifu的B树分配器PR已经通过审查并合并。</li></ul></li><li><p><strong>性能优化和后续行动</strong></p><ul><li>讨论了将数据定位器与混合合金和位图分配器结合形成混合模式的继续开发。</li><li>对OSD客户端消息容量（OSD client message cap）参数的调整进行了讨论，建议将其默认值设为256。</li></ul></li><li><p><strong>流控制和CPU分区</strong></p><ul><li>讨论了在客户端实现更精细的流控制机制的可能性，以及CPU分区的优化策略。</li><li>提到了在ARM架构上的测试结果，显示通过CPU分区可以获得性能提升。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>确认将OSD客户端消息容量参数的默认值调整为256。</li><li>需要进一步研究和测试细粒度锁定PR，以确保不会引入死锁问题。</li><li>计划在Intel平台上复现ARM架构上的CPU分区测试，以验证其效果。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>对细粒度锁定PR进行更深入的审查和测试。</li><li>在Intel平台上进行CPU分区测试，并与ARM架构上的结果进行对比。</li><li>继续推进数据定位器与混合合金和位图分配器的结合工作。</li></ul><h4 id="其他讨论" tabindex="-1">其他讨论 <a class="header-anchor" href="#其他讨论" aria-label="Permalink to &quot;其他讨论&quot;">​</a></h4><ul><li>讨论了在容器化环境中如何处理CPU分区的问题。</li><li>提到了在AWS上进行Graviton测试的可能性，以获取更多ARM架构的性能数据。</li></ul><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h3><p>本次会议重点讨论了Ceph项目的性能优化，包括新Pull Request的审查、性能参数的调整、流控制和CPU分区的策略。会议决定了后续行动计划，以确保Ceph项目的持续改进和发展。</p>',11)])])}const P=a(r,[["render",o]]);export{p as __pageData,P as default};
